INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261118-scharf-testimony-memo', 'white-house-counsel-scharf-memo-agency-testimony-congress-signoff', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'White House orders agencies to get its sign-off before any employee testifies to Congress', 'A memo from White House Counsel Will Scharf, dated Monday, Nov. 16, sets the rule weeks before Democrats take majorities in both chambers in January.', 'White House Counsel Will Scharf has told every executive branch agency that its employees may not testify before Congress without permission from the White House counsel''s office and the White House legislative affairs office, Axios reported in an exclusive on Monday, Nov. 16. The memo is dated the same day.

## The argument behind it

The memo follows a letter Scharf sent to Rep. Robert Garcia of California, the Democrat in line to chair the House Oversight Committee. That letter argued that congressional investigations must serve a legitimate legislative purpose and cannot be used to exercise prosecutorial powers, according to Axios. The memo states that Congress cannot use federal employees to exercise powers of criminal prosecution, Just Security''s daily roundup reported.

Axios noted that the White House''s own lawyers will decide which inquiries count as legitimate, a point Democrats are likely to dispute.

## Bracing for oversight

Democrats will hold majorities in both the House and Senate in January and have promised a wide range of investigations. Axios reported that the administration has been preparing for that moment for more than a year. A White House official told Axios the administration would not be "extorted, intimidated, or threatened" by what it called baseless investigations, but was ready to engage with Congress.

Axios also reported that Trump''s advisers do not believe the 67 Senate votes needed to remove a president after an impeachment would materialize, and that Trump has promised preemptive pardons for aides and allies he believes could be unfairly targeted.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Trump_Day_1_Executive_Order_Signing.jpg/1280px-Trump_Day_1_Executive_Order_Signing.jpg', 'President Trump signs executive orders on Jan. 20, 2025 (file). Official White House photo via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-18.sql', 8, 0, 'newsroom-assistant', '2026-11-18T10:55:00.000Z', '2026-11-18T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261118-scharf-testimony-memo-src1', 'bd-20261118-scharf-testimony-memo', 'Exclusive: White House requires signoff before agency staffers testify to Congress', 'https://axios.com/2026/11/16/exclusive-white-house-requires-signoff-before-agency-staffers-testify-to-congress', 'Axios', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-18T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-18. Editor to confirm.', 'newsroom-assistant', '2026-11-18T10:55:00.000Z');
