INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261118-iran-dirty-bomb-report', 'cnn-us-intelligence-iran-dirty-bomb-chemical-plans-washington-officials', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'U.S. intelligence points to Iranian planning for a dirty bomb or chemical attack on senior officials in Washington, CNN reports', 'Officials described options rather than an imminent plot. The White House said on Monday, Nov. 16, that there are no credible threats to the homeland.', 'New U.S. intelligence indicates Iran is developing options to attack senior Trump administration officials in Washington with a radiological "dirty bomb" or a chemical weapon, CNN reported on Monday, Nov. 16, citing seven U.S. officials.

## What officials described

The sources said the planning appears meant to give Tehran options rather than to signal an imminent attack, and officials disagreed about whether Iran could carry one out, according to CNN''s reporting as summarized by Just Security and FinChannel. Two sources said the intelligence named specific locations and targets and had prompted U.S. contingency planning.

## The responses

White House spokesperson Lauren Bis said the United States is monitoring all potential threats and that there are currently no credible threats to the homeland. The Office of the Director of National Intelligence declined to comment, and the Defense Department referred questions to that office, FinChannel reported.

Iran''s mission to the United Nations rejected allegations involving chemical weapons and called their use illegitimate, but did not directly address the dirty-bomb intelligence, according to the same report.

FinChannel also noted that a Justice Department announcement on Tuesday, Nov. 10, described an eight-count superseding indictment against three men accused of supporting an Iran-aligned network. That case does not list a radiological plot in Washington among its charges.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/An_aerial_view_of_the_Pentagon%2C_Washington%2C_D.C.%2C_May_15%2C_2023.jpg/1280px-An_aerial_view_of_the_Pentagon%2C_Washington%2C_D.C.%2C_May_15%2C_2023.jpg', 'An aerial view of the Pentagon, May 15, 2023 (file). U.S. Department of Defense photo via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-18.sql', 8, 0, 'newsroom-assistant', '2026-11-18T10:55:00.000Z', '2026-11-18T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261118-iran-dirty-bomb-report-src1', 'bd-20261118-iran-dirty-bomb-report', 'White House says no credible threat after Iran dirty bomb report', 'https://finchannel.com/white-house-says-no-credible-threat-after-iran-dirty-bomb-report/141930/americas/white-house-en/2026/11/', 'FinChannel (citing CNN)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-18T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-18. Editor to confirm.', 'newsroom-assistant', '2026-11-18T10:55:00.000Z');
