INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261118-senate-permitting-votes', 'senate-permitting-grid-bill-baaja-capito-substitute-votes-st-john-fifth-circuit', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 0, 'Senate heads to key votes on the bipartisan permitting and power-grid bill after a 70-27 test vote', 'Roll calls on the Capito substitute are expected around 11:45 a.m. on Wednesday, Nov. 18. On Tuesday, Nov. 17, the Senate confirmed Anna St. John to the Fifth Circuit, 52-46.', 'The Senate is set to resume work on the Bipartisan American Affordability and Jobs Act, H.R. 2347, at 10 a.m. on Wednesday, Nov. 18, with roll-call votes expected around 11:45 a.m., according to the Senate Periodical Press Gallery''s floor log. The votes cover adoption of a substitute amendment from Sen. Shelley Moore Capito (R-W.Va.), a possible budget point of order raised by Sen. Jeff Merkley (D-Ore.) and, if the bill is amended, a motion to end debate on the bill itself.

## What the bill would do

The Senate voted 70-27 on Monday, Nov. 16, to cut off debate on the substitute, The Hill reported. Capito wrote it with Sens. Sheldon Whitehouse (D-R.I.), Martin Heinrich (D-N.M.) and Mike Lee (R-Utah). It aims to speed approval of energy, mining and infrastructure projects, limit some legal challenges under federal environmental laws, and expand power-transmission capacity, cutting the time to build new lines from more than 10 years to about five or six, according to the report. Heinrich said it would make data centers pay for the power and grid upgrades they require.

President Trump backs the bill. Business groups, the AFL-CIO and the electrical workers'' union support it, while the Sierra Club and the Natural Resources Defense Council oppose it, The Hill reported. Merkley and nearly half of Senate Democrats are against it, and Sen. Catherine Cortez Masto (D-Nev.) has threatened to vote no unless a historic-preservation section is removed. A final Senate vote is expected before the Thanksgiving recess, and the House would still have to act.

## A judge confirmed

On Tuesday, Nov. 17, the Senate confirmed Anna St. John to the U.S. Court of Appeals for the Fifth Circuit by a party-line 52-46 vote, the floor log shows. Senators also passed, by unanimous consent, a resolution marking the death of former Sen. Jay Rockefeller of West Virginia before adjourning at 6:08 p.m.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Shelley_Moore_Capito_official_Senate_photo_(cropped_2).jpg/1280px-Shelley_Moore_Capito_official_Senate_photo_(cropped_2).jpg', 'Sen. Shelley Moore Capito, R-W.Va. (file). Official U.S. Senate photo via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-18.sql', 8, 0, 'newsroom-assistant', '2026-11-18T10:55:00.000Z', '2026-11-18T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261118-senate-permitting-votes-src1', 'bd-20261118-senate-permitting-votes', 'Tuesday, November 17, 2026 (Senate floor log)', 'https://www.dailypress.senate.gov/tuesday-november-17-2026/', 'U.S. Senate Daily Press Gallery', 'web', 'PRIMARY_SOURCE', 1, 1, '2026-11-18T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-18. Editor to confirm.', 'newsroom-assistant', '2026-11-18T10:55:00.000Z');
