INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261118-nc-house-recounts', 'virginia-foxx-recount-request-chuck-hubbard-nc-5th-district-335-votes', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Foxx asks for a recount after trailing Democrat Chuck Hubbard by 335 votes in North Carolina''s 5th District', 'Rep. Greg Murphy has conceded the neighboring 3rd District, and a Catawba County recount in the 10th District is set for Wednesday, Nov. 18. Nine House seats were still uncalled as of Monday, Nov. 16.', 'Rep. Virginia Foxx, the 83-year-old Republican who has held North Carolina''s 5th Congressional District for 21 years, requested a recount on Monday, Nov. 16, after final state tallies showed Democrat Chuck Hubbard ahead by 335 votes, WBTV reported. The state completed its canvass on Friday, Nov. 13.

## Why a recount is allowed

North Carolina law lets a trailing candidate in a race that is not statewide request a recount when the margin is within 1% of the votes cast. Foxx called the result historically close and said a recount was the most sensible way to ensure accuracy, according to WBTV. The station noted that her request did not yet appear on the state board''s public list of recount filings.

## The other close North Carolina races

As of Monday, Nov. 16, the Associated Press had not called nine of the 435 House races, three of them in North Carolina, Yahoo News reported. In the 3rd District, Republican Rep. Greg Murphy conceded after trailing Democrat Raymond Smith by 258 votes, about one-tenth of 1%. In the 10th District, Republican Rep. Pat Harrigan led Democrat Ashley Bell by 2,509 votes, 49.62% to 48.78%, and Bell requested a recount in Catawba County that is scheduled for Wednesday, Nov. 18.

Foxx''s current term ends on Jan. 3, 2027.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Virginia_Foxx_official_photo.jpg/1280px-Virginia_Foxx_official_photo.jpg', 'Rep. Virginia Foxx, R-N.C. (file). Official U.S. House photo via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-18.sql', 7, 0, 'newsroom-assistant', '2026-11-18T10:55:00.000Z', '2026-11-18T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261118-nc-house-recounts-src1', 'bd-20261118-nc-house-recounts', 'Republican rep. requests recount in tight US House race in North Carolina', 'https://www.wbtv.com/2026/11/17/republican-rep-requests-recount-tight-us-house-race-north-carolina/', 'WBTV', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-18T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-18. Editor to confirm.', 'newsroom-assistant', '2026-11-18T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261118-nc-house-recounts-src2', 'bd-20261118-nc-house-recounts', '9 House races remain too close to call. Three of them are in North Carolina', 'https://www.yahoo.com/news/politics/articles/10-house-races-remain-too-194827279.html', 'Yahoo News', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-18T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-18. Editor to confirm.', 'newsroom-assistant', '2026-11-18T10:55:00.000Z');
INSERT OR IGNORE INTO story_events (id, story_id, from_status, to_status, actor, note, created_at) VALUES ('bd-20261118-nc-house-recounts-ev1', 'bd-20261118-nc-house-recounts', NULL, 'EDITORIAL_REVIEW', 'newsroom-assistant', 'Drafted from attributed reporting and primary sources; awaiting editor approval', '2026-11-18T10:55:00.000Z');
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261118-boston-judges-foreign-students', 'boston-federal-judges-block-dhs-foreign-student-rules-cpt-duration-of-status', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Two federal judges in Boston rule against Homeland Security limits on international students on back-to-back days', 'Judge F. Dennis Saylor threw out a fixed time limit on student visas on Monday, Nov. 16. Judge Julia Kobick blocked new limits on students’ practical training on Tuesday, Nov. 17.', 'Federal judges in Boston ruled against two Department of Homeland Security policies on international students on consecutive days, according to reports from Reuters and ANI.

## Practical training restored

On Tuesday, Nov. 17, U.S. District Judge Julia Kobick barred DHS from enforcing two August directives that narrowed what counts as curricular practical training, the program that lets foreign students take internships and training for academic credit, Reuters reported. Under the directives, training qualified only if every student in a degree program had to complete it, which left out elective training taken for credit.

Kobick found the directives were likely arbitrary and capricious under the Administrative Procedure Act because DHS did not acknowledge it was reversing a long-standing interpretation. The suit was brought by four groups, including the Association of American Universities and the Presidents'' Alliance on Higher Education and Immigration. In 2024, 140,775 student visa holders were authorized for this kind of training, according to Immigration and Customs Enforcement figures cited by Reuters. DHS declined to comment.

## Time limit thrown out

A day earlier, on Monday, Nov. 16, U.S. District Judge F. Dennis Saylor vacated a DHS rule published in July that set a fixed period of admission for F-1 students, J-visa exchange visitors and I-visa foreign journalists and required them to apply for extensions, ANI reported. Saylor found the rule arbitrary and capricious, saying DHS did not properly weigh its costs and benefits, did not support its fraud and security claims and did not consider less restrictive options.

The plaintiffs in that case included NAFSA: Association of International Educators, the Association of Independent Colleges and Universities in Massachusetts, the American Federation of Teachers, the NewsGuild-CWA and the UAW. The court had already postponed the rule in September, and the government''s appeal of that order was pending at the First Circuit.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Moakley_Courthouse_and_Boston_Harborwalk_02.JPG/1280px-Moakley_Courthouse_and_Boston_Harborwalk_02.JPG', 'The John Joseph Moakley U.S. Courthouse on the Boston Harborwalk (file). Photo via Wikimedia Commons (free license; editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-18.sql', 7, 0, 'newsroom-assistant', '2026-11-18T10:55:00.000Z', '2026-11-18T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261118-boston-judges-foreign-students-src1', 'bd-20261118-boston-judges-foreign-students', 'US judge blocks Trump policy restricting foreign student work options', 'https://www.sowetan.co.za/news/world/2026-11-17-us-judge-blocks-trump-policy-restricting-foreign-student-work-options/', 'Reuters (via Sowetan)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-18T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-18. Editor to confirm.', 'newsroom-assistant', '2026-11-18T10:55:00.000Z');
