INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261118-kings-bruins', 'kings-3-bruins-0-kuemper-29-saves-boston-shut-out-third-straight-loss', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Kings 3, Bruins 0: Darcy Kuemper stops all 29 shots as Boston is shut out for the first time this season (Tue., Nov. 17)', 'Mats Zuccarello and Andre Lee scored and Erik Gustafsson added an empty-net goal at TD Garden. Both goalies stopped penalty shots, and the Bruins fell to 13-7-1 with a third straight loss.', 'The Los Angeles Kings beat the Bruins 3-0 at TD Garden on Tuesday, Nov. 17, handing Boston its first shutout loss of the season and its third defeat in a row, according to ESPN''s box score and a Yahoo Sports recap.

## How the goals came

Mats Zuccarello opened the scoring at 15:46 of the first period, putting in a rebound after a shot from Erik Gustafsson. Andre Lee made it 2-0 at 16:35 of the second, redirecting a Scott Laughton shot. Gustafsson finished it with an empty-net goal with 3:07 left in regulation.

Kings goalie Darcy Kuemper made 29 saves. Bruins goalie Michael DiPietro stopped 19 of the 21 shots he faced, according to ESPN.

## Two penalty shots, no goals

DiPietro stopped Quinton Byfield on a penalty shot at 5:56 of the second period, and Kuemper denied Morgan Geekie on another with 10:09 left in the third, Yahoo Sports reported. Boston gave up the first goal for the third straight game and went 9:18 without a shot late in the first period.

The Bruins are 13-7-1. Their next game is at Detroit.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/TD_Garden_(54960947755).jpg/1280px-TD_Garden_(54960947755).jpg', 'TD Garden, home of the Bruins, in Boston (file). Photo via Wikimedia Commons (free license; editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-18.sql', 7, 0, 'newsroom-assistant', '2026-11-18T10:55:00.000Z', '2026-11-18T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261118-kings-bruins-src1', 'bd-20261118-kings-bruins', 'Bruins Shut Out By Kings, Lose Third Straight', 'https://sports.yahoo.com/articles/bruins-shut-kings-lose-third-024016878.html', 'Yahoo Sports', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-18T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-18. Editor to confirm.', 'newsroom-assistant', '2026-11-18T10:55:00.000Z');
