INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261118-patriots-chargers-flex', 'nfl-flexes-patriots-chargers-out-of-sunday-night-vrabel-no-qb-signing-maye', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'NFL moves Patriots-Chargers out of Sunday night after Drake Maye’s injury, and Vrabel says he does not plan to add a quarterback', 'The Week 12 game shifts to 4:05 p.m. ET on CBS on Sunday, Nov. 29. Raiders-Browns takes the 8:20 p.m. NBC slot.', 'The NFL on Tuesday, Nov. 17, moved the Patriots'' Week 12 game against the Los Angeles Chargers out of prime time, Boston.com and CBS Sports reported. The game at SoFi Stadium was scheduled for 8:20 p.m. ET on NBC''s Sunday Night Football on Sunday, Nov. 29. It will now kick off at 4:05 p.m. ET on CBS.

## The new Sunday night game

The Las Vegas Raiders at the Cleveland Browns moves from 1 p.m. to the 8:20 p.m. NBC slot on Nov. 29, and the Tennessee Titans at the Jacksonville Jaguars moves from 4:05 p.m. to 1 p.m. on Fox, according to CBS Sports. The league did not give a reason. Boston.com suggested that quarterback Drake Maye''s injury made the Patriots a less attractive prime-time draw.

## The quarterback question

Maye was hurt on the Patriots'' first drive of their 35-10 loss to the Detroit Lions in Germany on Sunday, Nov. 15, and is expected to miss an extended period. Coach Mike Vrabel said after the game that he did not see the team signing another quarterback "right now," though it would keep looking at options, Yahoo Sports reported. Tommy DeVito is expected to start, with rookie Behren Morton also on the roster. Insider Jordan Schultz reported that New England is expected to explore the quarterback market during its bye week.

The Patriots are 5-5. The Chargers are 1-8 after beating the Baltimore Ravens 23-20 on Monday, Nov. 16.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Patriots_on_offense_at_Super_Bowl_XXXIX_1.jpg/1280px-Patriots_on_offense_at_Super_Bowl_XXXIX_1.jpg', 'The Patriots on offense at Super Bowl XXXIX in Jacksonville, February 2005 (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-18.sql', 6, 0, 'newsroom-assistant', '2026-11-18T10:55:00.000Z', '2026-11-18T10:55:00.000Z');
